#include <set>
#include <stdexcept>

struct ThrowingComp {
    bool operator()(int a, int b) const { return a < b; }
    // If copy constructor for this struct threw, swap() might fail.
};

void safe_insert(std::set<int>& s, int val) {
    try {
        // Strong guarantee: either succeeds or the container is unchanged
        s.insert(val);
    } catch (const std::exception& e) {
        // s is guaranteed to be valid and unchanged
        // if insertion failed due to internal allocation.
    }
}
